std::vector<int> vec = {10, 20, 30};

// Size: Number of elements currently held
size_t current_size = vec.size(); // 3

// Capacity: Allocated storage space
size_t alloc_cap = vec.capacity(); // >= 3

// Check if vector is empty (O(1) complexity)
bool is_empty = vec.empty();

// Resize changes size (adds/removes elements, initializes new ones)
vec.resize(5, 50); // vec: {10, 20, 30, 50, 50}
vec.resize(2);     // vec: {10, 20}
// Capacity may remain high even if size drops

std::vector<int> data = {1, 2, 3};

// Direct element access (No bounds check, fast, unsafe)
int x = data[0]; // 1
// data[99] = 0; // WARNING: Undefined Behavior!

// Bounds-checked access (Safe, throws std::out_of_range)
try {
    int y = data.at(1); // 2
    data.at(3) = 0;     // Throws exception
} catch (const std::out_of_range& e) {
    // Handle error
}

// Accessing start/end elements
int front = data.front(); // 1
int back = data.back();   // 3 (If size > 0)

// Direct pointer access to underlying array
int* raw_ptr = data.data();
// raw_ptr[0] is equivalent to data[0]
